+      this.phase = 'work';
+      this.working = true;
+      this.faceTowards(target.x, target.y);
+      this.workAnim += sdt;
+      if (ranged) this.tryShoot(target);
+      else this.tryMelee(target);
+      return;
+    }
+    this.phase = 'go';
+    this.working = false;
+    this.repathTimer -= sdt;
+    if (!this.path.length || this.repathTimer <= 0) {
