      ctx.strokeStyle = app.pants || '#3f4a52';
      ctx.lineWidth = 3.6;
      ctx.beginPath();
      ctx.moveTo(off * 0.6, -8);
      ctx.lineTo(ex, 1);
      ctx.stroke();
      // boot
      ctx.fillStyle = '#3a2b20';
      roundRect(ctx, ex - 2.1, -0.4, 4.6, 3.2, 1.4); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.08)';
