      this.marquee = null;
      this.renderer.marquee = null;
      if (m.moved) this.applyMarquee(m);
      else this.tap(s, e);
      return;
    }
  }

  endPan() {
    if (this.pan) this.pan = null;
    this.canvas.classList.remove('grabbing');
  }

  // ---------------------------------------------------------------- tap / select
  tap(s, e = {}) {
    const p = this.renderer.screenToWorld(s.x, s.y);
