    if (ndef.rank === 8) {
      ctx.fillStyle = 'rgba(0,0,0,0.12)';
      this.edgeRect(ctx, px, py, dx, dy, 0, 2.6);
      continue;
    }

    // Higher-ranked neighbouring terrain spills into this tile with an organic edge.
    if (ndef.rank > def.rank && ndef.rank < 6) {
