      ctx.fillRect(x, by, TILE, 8);
      ctx.fillStyle = 'rgba(41,24,10,0.52)';
      ctx.fillRect(x, by, TILE, 1.3);
      ctx.fillStyle = 'rgba(255,228,182,0.10)';
      ctx.fillRect(x, by + 1.3, TILE, 0.9);
      ctx.fillStyle = 'rgba(35,20,8,0.44)';
